/**
 * Abstract base class for paginated query operations.
 * Subclasses implement the actual data-loading logic.
 * Call {@link loadNextPage} to fetch the next page of results.
 *
 * @typeParam T - The type of the query result data
 * @typeParam P - The type of the query parameters
 *
 * @example
 * ```ts
 * const query = BaseChannel.createChannelsQuery({ pageSize: 20 });
 * const result = await query.loadNextPage();
 * if (result.isOk) {
 *   console.log('Channels:', result.data);
 * }
 * ```
 */
